screenPanels.initJs:
function(container, apiUrl, tables) {
  const PAGE_SIZE = 20;
  let allLogs = [];
  let filteredLogs = [];
  let currentPage = 1;

  const timeline = container.querySelector('#log-timeline');
  const logCountEl = container.querySelector('#log-count');
  const logPageEl = container.querySelector('#log-page');
  const template = container.querySelector('#log-entry-template');

  const userFilterEl = container.querySelector('[data-testid="user-filter"]');
  const dateFromEl = container.querySelector('[data-testid="date-from"]');
  const dateToEl = container.querySelector('[data-testid="date-to"]');
  const opTypeFilterEl = container.querySelector('[data-testid="operation-type-filter"]');
  const customerSearchEl = container.querySelector('[data-testid="customer-search"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const prevPageBtn = container.querySelector('[data-testid="prev-page-button"]');
  const nextPageBtn = container.querySelector('[data-testid="next-page-button"]');

  // Load logs from API
  async function loadLogs() {
    try {
      allLogs = await window.aivicApi.list(0) || [];
      // Sort by datetime descending (newest first)
      allLogs.sort((a, b) => new Date(b.datetime || 0) - new Date(a.datetime || 0));
      filteredLogs = [...allLogs];
      currentPage = 1;
      renderLogs();
    } catch (err) {
      console.error('Failed to load logs:', err);
      timeline.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 24px;">ログの読み込みに失敗しました</div>';
    }
  }

  // Apply filters
  function applyFilters() {
    const userFilter = userFilterEl.value.toLowerCase();
    const dateFrom = dateFromEl.value ? new Date(dateFromEl.value) : null;
    const dateTo = dateToEl.value ? new Date(dateToEl.value) : null;
    const opTypeFilter = opTypeFilterEl.value;
    const customerSearch = customerSearchEl.value.toLowerCase();

    filteredLogs = allLogs.filter(log => {
      // User filter
      if (userFilter && !(log.user || '').toLowerCase().includes(userFilter)) return false;

      // Date range filter
      if (dateFrom || dateTo) {
        const logDate = new Date(log.datetime || 0);
        if (dateFrom && logDate < dateFrom) return false;
        if (dateTo && logDate > dateTo) return false;
      }

      // Operation type filter
      if (opTypeFilter && log.operationType !== opTypeFilter) return false;

      // Customer search
      if (customerSearch) {
        const custId = (log.customerId || '').toLowerCase();
        const custName = (log.customerName || '').toLowerCase();
        if (!custId.includes(customerSearch) && !custName.includes(customerSearch)) return false;
      }

      return true;
    });

    currentPage = 1;
    renderLogs();
  }

  // Render logs
  function renderLogs() {
    timeline.innerHTML = '';

    if (filteredLogs.length === 0) {
      timeline.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 24px; font-size: 13px;">該当するログがありません</div>';
      logCountEl.textContent = '0';
      logPageEl.textContent = '1';
      return;
    }

    const start = (currentPage - 1) * PAGE_SIZE;
    const end = start + PAGE_SIZE;
    const pageLogs = filteredLogs.slice(start, end);

    pageLogs.forEach(log => {
      const card = template.content.cloneNode(true);
      const entry = card.querySelector('.log-entry-card');

      // Populate card
      card.querySelector('.log-user').textContent = log.user || '-';
      card.querySelector('.log-datetime').textContent = formatDateTime(log.datetime);
      card.querySelector('.log-type').textContent = log.operationType || '-';
      card.querySelector('.log-customer').textContent = `${log.customerId || '-'} / ${log.customerName || '-'}`;
      card.querySelector('.log-id').textContent = log.id || '-';
      card.querySelector('.log-detail').textContent = log.detail || '-';

      // Show/hide details based on operation type
      const detailsDiv = card.querySelector('.log-details');
      const changesDiv = card.querySelector('.log-changes');
      const reasonDiv = card.querySelector('.log-reason');

      if (log.operationType === '修正' && log.changes) {
        changesDiv.style.display = 'block';
        const tbody = card.querySelector('.changes-tbody');
        tbody.innerHTML = '';
        log.changes.forEach(change => {
          const row = document.createElement('tr');
          row.style.borderBottom = '1px solid var(--border)';
          row.innerHTML = `
            <td style="padding: 6px; color: var(--text);">${change.field || '-'}</td>
            <td style="padding: 6px; color: var(--text-muted); text-decoration: line-through;">${change.before || '-'}</td>
            <td style="padding: 6px; color: var(--primary); font-weight: 500;">${change.after || '-'}</td>
          `;
          tbody.appendChild(row);
        });
      }

      if (log.operationType === '統合判定' && log.reason) {
        reasonDiv.style.display = 'block';
        card.querySelector('.reason-text').textContent = log.reason;
      }

      // Toggle expand/collapse
      entry.addEventListener('click', () => {
        const isExpanded = detailsDiv.style.display !== 'none';
        detailsDiv.style.display = isExpanded ? 'none' : 'block';
        const icon = card.querySelector('.expand-icon');
        icon.textContent = isExpanded ? '▼' : '▲';
        entry.style.background = isExpanded ? 'var(--bg-card)' : 'var(--bg-main)';
      });

      timeline.appendChild(card);
    });

    // Update pagination
    const totalPages = Math.ceil(filteredLogs.length / PAGE_SIZE);
    logCountEl.textContent = filteredLogs.length;
    logPageEl.textContent = currentPage;
    prevPageBtn.disabled = currentPage === 1;
    nextPageBtn.disabled = currentPage >= totalPages;
    prevPageBtn.style.opacity = currentPage === 1 ? '0.5' : '1';
    nextPageBtn.style.opacity = currentPage >= totalPages ? '0.5' : '1';
  }

  // Format datetime
  function formatDateTime(dt) {
    if (!dt) return '-';
    const d = new Date(dt);
    return d.toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  }

  // Export CSV
  function exportCSV() {
    if (filteredLogs.length === 0) {
      alert('エクスポートするログがありません');
      return;
    }

    const headers = ['操作者', '操作日時', '操作種別', '顧客ID', '顧客名', '操作ID', '詳細'];
    const rows = filteredLogs.map(log => [
      log.user || '',
      formatDateTime(log.datetime),
      log.operationType || '',
      log.customerId || '',
      log.customerName || '',
      log.id || '',
      log.detail || ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `audit-log-${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // Event listeners
  searchBtn.addEventListener('click', applyFilters);
  exportBtn.addEventListener('click', exportCSV);
  prevPageBtn.addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderLogs();
      timeline.scrollTop = 0;
    }
  });
  nextPageBtn.addEventListener('click', () => {
    const totalPages = Math.ceil(filteredLogs.length / PAGE_SIZE);
    if (currentPage < totalPages) {
      currentPage++;
      renderLogs();
      timeline.scrollTop = 0;
    }
  });

  // Initial load
  loadLogs();
}
